9: static NSString * const RSNotification = @"com.tu.recordingsharingan.settings.changed";
10: static NSString * const RSDomain = @"com.tu.recordingsharingan.settings";
11: static void RSWrite(NSString *key, id value) {
12:     CFPreferencesSetAppValue((__bridge CFStringRef)key, (__bridge CFPropertyListRef)value, (__bridge CFStringRef)RSDomain);
13:     CFPreferencesAppSynchronize((__bridge CFStringRef)RSDomain);
14:     CFNotificationCenterPostNotification(CFNotificationCenterGetDarwinNotifyCenter(), (__bridge CFStringRef)RSNotification, NULL, NULL, YES);
15: }
16: @interface RSStepSliderCell : PSSliderTableCell
17: @property(nonatomic,strong) UIButton *minusButton;
18: @property(nonatomic,strong) UIButton *plusButton;
19: @end
20: @implementation RSStepSliderCell
21: - (id)initWithStyle:(UITableViewCellStyle)style reuseIdentifier:(NSString *)identifier specifier:(PSSpecifier *)specifier {
22:     self = [super initWithStyle:style reuseIdentifier:identifier specifier:specifier];
23:     if (self) {
24:         _minusButton = [UIButton buttonWithType:UIButtonTypeSystem];
25:         _plusButton = [UIButton buttonWithType:UIButtonTypeSystem];
26:         for (UIButton *button in @[_minusButton,_plusButton]) {
27:             button.titleLabel.font = [UIFont systemFontOfSize:13 weight:UIFontWeightSemibold];
28:             button.backgroundColor = [UIColor colorWithWhite:0.94 alpha:1];
29:             button.layer.cornerRadius = 4;
30:             [self.contentView addSubview:button];
31:         }
32:         [_minusButton setTitle:@"−" forState:UIControlStateNormal];
33:         [_plusButton setTitle:@"+" forState:UIControlStateNormal];
34:         [_minusButton addTarget:self action:@selector(decrement) forControlEvents:UIControlEventTouchUpInside];
35:         [_plusButton addTarget:self action:@selector(increment) forControlEvents:UIControlEventTouchUpInside];
36:     }
37:     return self;
38: }
39: - (void)layoutSubviews {
40:     [super layoutSubviews];
41:     UISlider *slider = nil;
42:     for (UIView *view in self.contentView.subviews) if ([view isKindOfClass:[UISlider class]]) { slider=(UISlider *)view; break; }
43:     if (!slider) return;
44:     CGRect f=slider.frame;
45:     CGFloat w=self.contentView.bounds.size.width;
46:     // Keep the native slider's vertical placement and leave room for step buttons.
47:     CGFloat buttonSize=22;
48:     _minusButton.frame=CGRectMake(MAX(8,CGRectGetMinX(f)-buttonSize-5),CGRectGetMidY(f)-11,buttonSize,buttonSize);
49:     _plusButton.frame=CGRectMake(MIN(w-buttonSize-45,CGRectGetMaxX(f)+4),CGRectGetMidY(f)-11,buttonSize,buttonSize);
50:     CGFloat start=CGRectGetMaxX(_minusButton.frame)+5;
51:     CGFloat end=CGRectGetMinX(_plusButton.frame)-5;
52:     if (end>start+45) slider.frame=CGRectMake(start,f.origin.y,end-start,f.size.height);
53: }
54: - (void)decrement { [self change:-1]; }
55: - (void)increment { [self change:1]; }
56: - (void)change:(NSInteger)direction {
57:     NSString *key=[self.specifier propertyForKey:@"key"];
58:     if (!key) return;
59:     double step=[[self.specifier propertyForKey:@"step"] doubleValue]; if(step<=0)step=0.5;
60:     double lo=[[self.specifier propertyForKey:@"min"] doubleValue];
61:     double hi=[[self.specifier propertyForKey:@"max"] doubleValue];
62:     CFPropertyListRef current=CFPreferencesCopyAppValue((__bridge CFStringRef)key,(__bridge CFStringRef)RSDomain);
63:     double value=current ? [(__bridge id)current doubleValue] : [[self.specifier propertyForKey:@"default"] doubleValue];
64:     if(current)CFRelease(current);
65:     value=MIN(hi,MAX(lo,round((value+direction*step)/step)*step));
66:     RSWrite(key,@(value));
67:     UISlider *slider=nil;
68:     for(UIView *view in self.contentView.subviews)if([view isKindOfClass:[UISlider class]]){slider=(UISlider *)view;break;}
69:     if(slider){[slider setValue:value animated:YES];[slider sendActionsForControlEvents:UIControlEventValueChanged];}
70: }
71: @end
